    let goal = arena.boolean(false);
    let budget = lg_budget();
    let base = sv_engine_name(engine);
    let settings = sv_engine_settings(engine);
    if (base == "new" || base == "new-fm" || base == "new-simplex") && !defs.is_empty() { return sv_nl_line(&arena, &script.assertions, goal, &budget, &status, &sv_new_theory(&base), &reals, settings, &defs); }
